entries[224078] = { ["name"] = "Schild des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Schild\n28 Rüstung\n+13 Stärke\n+13 Beweglichkeit\n+17 Intelligenz\n80 ( 80)" }
entries[224079] = { ["name"] = "Streitkolben des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n3 - 4 Schaden Geschwindigkeit 2.60\n(1.3 Schaden pro Sekunde)\n+13 Stärke\n+13 Beweglichkeit\n+17 Intelligenz\n80 ( 80)" }
entries[224080] = { ["name"] = "Schwert des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n2 - 4 Schaden Geschwindigkeit 2.60\n(1.2 Schaden pro Sekunde)\n+13 Stärke\n+13 Beweglichkeit\n+17 Intelligenz\n80 ( 80)" }
entries[224081] = { ["name"] = "Stab des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stab\n5 - 8 Schaden Geschwindigkeit 3.60\n(1.8 Schaden pro Sekunde)\n+25 Stärke\n+25 Beweglichkeit\n+34 Intelligenz\n80 ( 80)" }
entries[224098] = { ["name"] = "Blutroter Bezauberer", ["text"] = "Questgegenstand\n\"Aemyra sagte mir, dass das ihre Lieblingsblume sei, weil ihre rote Farbe so schön ist.\"" }
entries[224099] = { ["name"] = "Bernblüte", ["text"] = "Questgegenstand\n\"Die Arathi sagen, dass Bernblüten sie an ihren Stern Beledar erinnern. Sie sehen irgendwie wie Elizas Entscheidungszahnräder aus.\"" }
entries[224100] = { ["name"] = "Bodenlose Tasche voller Khaz-Algar-Gemischtwaren", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält viele gewöhnliche Reagenzien, die alle Berufe benötigen. Euch fehlt immer noch etwas? Fragt einen Händler!\"\n<Zum Öffnen rechtsklicken>" }
entries[224101] = { ["name"] = "Braune Laubwanze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[224102] = { ["name"] = "Zerstückelte Kobyssinnereien", ["text"] = "Questgegenstand\n\"Viele kleine Stücke. Geraten in viele kleine Ecken.\"" }
entries[224103] = { ["name"] = "Undefinierbare Kobyssinnereien", ["text"] = "Questgegenstand\n\"Zu welchem Organ soll das gehören?\"" }
entries[224104] = { ["name"] = "Feuerblitzräucherwerkkugel", ["text"] = "Questgegenstand\nBenutzen: Ein heiliges Feuer, das Nachtschattenentführer in Bummelgau aufdeckt und betäubt. (2 Sek. Abklingzeit)\n\"Eine kleine, zerbrechliche Glaskugel, die beim Zerschmettern einen gewaltigen Blitz und Knall erzeugt.\"" }
entries[224114] = { ["name"] = "Runenverzierte Bismutrute", ["text"] = "Wird beim Anlegen gebunden\nWerkzeug für Verzauberkunst + 80 Zufallswert 1\nAnlegen: +8 Fertigkeit in Verzauberkunst von Khaz Algar\n\"Dient als runenverzierte Verzauberkunstrute.\"\nVerkaufspreis:" }
entries[224115] = { ["name"] = "Runenverzierte Eisenklauenrute", ["text"] = "Wird beim Aufheben gebunden\nWerkzeug für Verzauberkunst + 125 Zufallswert 1\nAnlegen: +18 Fertigkeit in Verzauberkunst von Khaz Algar\n\"Dient als runenverzierte Verzauberkunstrute.\"\nVerkaufspreis:" }
entries[224116] = { ["name"] = "Runenverzierte Nullsteinrute", ["text"] = "Wird beim Aufheben gebunden\nWerkzeug für Verzauberkunst + 125 Zufallswert 1\nAnlegen: +18 Fertigkeit in Verzauberkunst von Khaz Algar\nAnlegen: Ihr braucht 1% weniger Konzentration bei Verzauberkunstformeln von Khaz Algar.\n\"Dient als runenverzierte Verzauberkunstrute.\"\nVerkaufspreis:" }
entries[224118] = { ["name"] = "Nachtschattenbrief", ["text"] = "Questgegenstand\n\"Dieser Brief erwähnt einige \"neue Freunde\", die in der Umgebung mit dem Orden der Nacht zusammenarbeiten.\"\n<Zum Lesen rechtsklicken>" }
entries[224119] = { ["name"] = "Zitteraal", ["text"] = "\"Tot, zuckt aber noch vor verbleibender elektrischer Ladung. Diese Aale sind das Lieblingsessen von Wolkenkrähen und Sturmkrähen.\"" }
entries[224120] = { ["name"] = "Edelsteinschatulle des Zeitläufers", ["text"] = "Wird beim Aufheben gebunden\n80 ( 80)\n<Zum Öffnen rechtsklicken>" }
entries[224146] = { ["name"] = "Archäologiefragmente aus Khaz Algar", ["text"] = "Questgegenstand\n\"Ein Stück der Geschichte von Khaz Algar. Es mag nicht ganz sein, doch ein Stück ist besser als kein Stück.\"" }
entries[224147] = { ["name"] = "Zügel des Himmelsreißers der Sureki", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der Himmelsreißer war eine der brutalsten Monstrositäten, die aus Königin Ansureks Experimenten mit dem Schwarzblut der Alten Götter hervorgegangen sind.\"\nBeute von:\nKönigin Ansurek\nZone:\nPalast der Nerub'ar" }
entries[224150] = { ["name"] = "Siesbarg", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Armer Kerl.\"\nWeltquest:\nTrostfliegen\nZone:\nAzj-Kahet\nZone:\nStadt der Fäden" }
entries[224151] = { ["name"] = "Zügel des aufsteigenden Himmelsreißers", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Himmelsreißer sind nur für die Ergebensten der Surekielite gedacht und waren wegen ihres Muts und ihrer Brutalität die Lieblinge von Königin Ansurek.\"\nBeute von:\nKönigin Ansurek\nZone:\nPalast der Nerub'ar (Mythisch)" }
entries[224152] = { ["name"] = "Rezept: Herzhafter Kaiserinnenabschied", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen herzhaften Kaiserinnenabschied herstellt.\nRezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nVerkaufspreis:" }
