entries[224154] = { ["name"] = "Pilzstein", ["text"] = "\"Es ist unklar, ob es sich hier um ein versteinertes Stück Schimmel, einen sehr schimmligen Steinbrocken oder beides gleichzeitig handelt.\"\nVerkaufspreis:" }
