entries[224157] = { ["name"] = "Haustierspiegel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Nehmt das Aussehen Eures Haustiers an. Funktioniert nur bei Haustieren, die kämpfen können. (10 Min Abklingzeit)" }
entries[224158] = { ["name"] = "Branns Brieföffner", ["text"] = "Questgegenstand\n\"Ein viel benutzter Brieföffner. Trägt dem Anschein nach Bronzebartheraldik auf dem Griff.\"" }
entries[224159] = { ["name"] = "Branns Kompass", ["text"] = "Questgegenstand\n\"Auf der Rückseite ist eine Inschrift: \"Brann, mögest du stets den Weg nach Hause finden.\"\"" }
entries[224160] = { ["name"] = "Branns Hut", ["text"] = "Questgegenstand\n\"Ihr blickt kurz zu dem Hut auf Branns Kopf und dann zurück zu diesem. Es ist unmöglich, die beiden zu unterscheiden.\"" }
entries[224161] = { ["name"] = "Sturmreiterflugabzeichen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.502 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Fähigkeiten haben eine Chance, Euer Tempo 12 Sek. lang um 2489 zu erhöhen.\nVerkaufspreis:" }
