entries[224179] = { ["name"] = "Schlammiger Brief", ["text"] = "Questgegenstand\n\"Das Pergament des Briefes ist intakt, doch Dreck und Schlamm haben die Schrift unleserlich gemacht.\"" }
entries[224180] = { ["name"] = "Abgenutztes Tagebuch", ["text"] = "Questgegenstand\n\"Dieses Tagebuch enthält Einträge über die Wildnis außerhalb von Dornogal.\"" }
