entries[224182] = { ["name"] = "Eingewebte Barren", ["text"] = "Questgegenstand\n\"Diese Barren könnten noch verwendet werden, wenn jemand die Spinnweben abbekommt.\"" }
entries[224183] = { ["name"] = "Trostloser Köder", ["text"] = "Questgegenstand\nEinzigartig (3)\n\"Ein besonders reizender Leckerbissen aus Knorpel und Eingeweiden.\"" }
entries[224184] = { ["name"] = "Verkrustetes Fernrohr", ["text"] = "Questgegenstand\n\"Bei dem Fernrohr scheint es sich um Massenware ohne Anhaltspunkte auf seinen ehemaligen Besitzer zu handeln.\"" }
entries[224185] = { ["name"] = "Krabbenführender Ast", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Führt eine irisierende Panzerkrabbe zu Freyschwörerin Letitia zurück.\n80 ( 80)\n\"Der Schlüssel zum Höhlenbaummysterium.\"" }
entries[224186] = { ["name"] = "Hymnen der Flamme", ["text"] = "Questgegenstand\n\"Der Inhalt des Buches straft seinen Titel lügen.\"" }
entries[224187] = { ["name"] = "Verbeulte Speerspitze", ["text"] = "Questgegenstand\n\"Dieser von Kampfspuren übersäte Speerkopf ist an einer Kette befestigt. Es scheint sich um eine Art Trophäe zu handeln.\"" }
entries[224188] = { ["name"] = "Filigraner Kleriker", ["text"] = "Questgegenstand\n\"Auch wenn die Machart dieser Spielfigur für Schachzug des Lichts darauf deutet, dass sie zur Dekoration gedacht ist, weißt sie beträchtliche Abnutzungsspuren auf.\"" }
entries[224189] = { ["name"] = "Elfenbeinzunderkasten", ["text"] = "Questgegenstand\n\"Ein mit Elfenbein unbekannten Ursprungs verzierter Zunderkasten. In den Deckel wurde eine edle Figur geschnitzt.\"" }
entries[224190] = { ["name"] = "Kreegs kräftiges Gebräu", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erlebt eine düstere Lage.\nAbklingzeit während des Geburtstags von WoW verringert. (30 Min Abklingzeit)\n5 Aufladungen\n\"So ein starkes Getränk hat sicher Nachwirkungen...\"" }
entries[224192] = { ["name"] = "Übungsverheerer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Drehen für den Sieg! (10 Min Abklingzeit)\n\"Herod hat jahrelang geübt, bevor er sein berühmtes Abschlussmanöver enthüllte.\"" }
entries[224193] = { ["name"] = "Orrens Nachricht", ["text"] = "Questgegenstand\n\"Eine einfühlsame Nachricht an meine wahre Liebe, Aemyra.\"\n<Zum Lesen rechtsklicken>" }
entries[224194] = { ["name"] = "Schleife des Moderauschs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stimmt für Eure Lieblingsvorlage! (10 Sek. Abklingzeit)\n\"Stimmt für eure Lieblings-Transmogs!\"" }
