entries[224232] = { ["name"] = "Faulende Kobyssinnereien", ["text"] = "Questgegenstand\n\"Dieses Fleischs ist eine Offenbarung für Euch: Die Kobyss können keinen Geruchssinn haben.\"" }
entries[224238] = { ["name"] = "Abgenutzte Münze", ["text"] = "Questgegenstand\n\"Eine kleine Kupfermünze mit fremder Prägung.\"" }
entries[224239] = { ["name"] = "Haufen aus Lederbändern", ["text"] = "Questgegenstand\n\"Eine Ansammlung an Pilotenhaarbändern, die sich zu einem einzigen Durcheinander verknotet haben.\"" }
entries[224240] = { ["name"] = "Nerubergrabstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ehrt die Toten, wie die Neruber es tun. (1 Min Abklingzeit)\n\"Kriege gegen die Geißel haben die Neruber gelehrt, ihre Toten einzuäschern, doch sie verwenden nach wie vor Grabsteine, um ihrer Gefallenen zu gedenken.\"\nVerkaufspreis:" }
