entries[224250] = { ["name"] = "Spielzeugfisch", ["text"] = "Questgegenstand\n\"Ein großer Fisch aus Holz und Leder. Er hat mehrere große Furchen an der Außenseite.\"" }
entries[224251] = { ["name"] = "Erinnerungsakkord", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Entfesselt eine Erinnerung an Euch selbst. (5 Min Abklingzeit)\n\"Aus einer Lebzeit an Erinnerungen gewonnen.\"\nVerkaufspreis:" }
entries[224252] = { ["name"] = "Kalzifiziertes Tagebuch", ["text"] = "Questgegenstand\n\"Beim Aufbrechen des Buches stellt sich heraus, dass die Seiten in der Mitte noch größtenteils intakt sind. Sie sind voller Zeichnungen einer Euch unbekannten Landschaft.\"" }
entries[224253] = { ["name"] = "Elementaraktive Kohle", ["text"] = "Questgegenstand\n\"Selbst jetzt rumpeln kleine Kohlestücke aggressiv auf Euch zu, wenn sie nicht gesichert sind.\"" }
entries[224254] = { ["name"] = "Hölzerne Figur", ["text"] = "Questgegenstand\n\"Eine grob geschnitzte Statue. Sie stellt einen Luchs dar, der durch Flammen rennt.\"" }
entries[224256] = { ["name"] = "Beutel mit wütenden Fungi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lasst einen Sack voller wütender Fungi frei, die allen Gegnern in der Nähe Schaden zufügen und sie 30 Sek. ablenken.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten. (1 Min Abklingzeit)\n\"Der Beutel ist recht unruhig.\"" }
entries[224257] = { ["name"] = "Robustes Medaillon", ["text"] = "Questgegenstand\n\"Wo sich für gewöhnlich ein Porträt befindet, ist stattdessen eine Blume zwischen Glas gepresst und präserviert.\"" }
entries[224259] = { ["name"] = "Blitz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[224260] = { ["name"] = "Thundo", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[224261] = { ["name"] = "Heftiger Wind", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[224262] = { ["name"] = "Widerwillig eingeschenktes Glutbräu.", ["text"] = "Questgegenstand\n\"So brennend heiß wie Gastwirt Brax' Zorn. Schmeckt allerdings besser.\"" }
entries[224263] = { ["name"] = "Energieerfüllte Feuerhonigmilch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nWenn Ihr tödlichen Schaden erleidet, könnt Ihr einen letzten Trank zu Euch nehmen, der Euch einen Schild verleiht, der Schaden in Höhe von 25% Eurer maximalen Gesundheit für 15 Sek. absorbiert. Solange der Schild hält, wird Euer Primärwert um 2553 erhöht.\n\nDieser Effekt kann nur einmal alle 5 Min. auftreten, solange Ihr Euch im Freien von Khaz Algar aufhaltet.\nVerkaufspreis:" }
entries[224264] = { ["name"] = "Tiefenhainblüte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen von Khaz Algar um 1 zu erhöhen.\nBenötigt Kräuterkunde von Khaz Algar (1)" }
entries[224265] = { ["name"] = "Tiefenhainrose", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen von Khaz Algar um 4 zu erhöhen.\n\"Ihr vermutet, dass es ein Weilchen dauert, bis Ihr wieder eine ausgewachsene Tiefenhainrose findet.\"" }
entries[224266] = { ["name"] = "Elfenbeinzunderkasten", ["text"] = "Wird beim Aufheben gebunden\n\"Ein mit Elfenbein unbekannten Ursprungs verzierter Zunderkasten. In den Deckel wurde eine edle Figur geschnitzt.\"" }
entries[224267] = { ["name"] = "Verbeulte Speerspitze", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser von Kampfspuren übersäte Speerkopf ist an einer Kette befestigt. Es scheint sich um eine Art Trophäe zu handeln.\"" }
entries[224268] = { ["name"] = "Filigraner Kleriker", ["text"] = "Wird beim Aufheben gebunden\n\"Auch wenn die Machart dieser Spielfigur für Schachzug des Lichts darauf deutet, dass sie zur Dekoration gedacht ist, weißt sie beträchtliche Abnutzungsspuren auf.\"" }
entries[224270] = { ["name"] = "Technik: Zerfleddertes Besitzzertifikat", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein zerfleddertes Besitzzertifikat herstellt.\nBenötigt Klassische Inschriftenkunde (1)\nVerkaufspreis:\nZerfleddertes Besitzzertifikat\nKlassen: Jäger\n\"Eine Urkunde für ein innig geliebtes Haustier.\"\nVerkaufspreis:\nBenötigt Leichtes Pergament , Firmamenttinte (2)" }
entries[224271] = { ["name"] = "Galvanische Drüse", ["text"] = "Questgegenstand\n\"Maschinenflüsterer in entlegenen Regionen haben gelernt, sie als vorübergehende Batterien zu verwenden.\"" }
entries[224272] = { ["name"] = "Kalzifiziertes Tagebuch", ["text"] = "Wird beim Aufheben gebunden\n\"Beim Aufbrechen des Buches stellt sich heraus, dass die Seiten in der Mitte noch größtenteils intakt sind. Sie sind voller Zeichnungen einer Euch unbekannten Landschaft.\"" }
entries[224273] = { ["name"] = "Hölzerne Figur", ["text"] = "Wird beim Aufheben gebunden\n\"Eine grob geschnitzte Statue. Sie stellt einen Luchs dar, der durch Flammen rennt.\"" }
entries[224274] = { ["name"] = "Robustes Medaillon", ["text"] = "Wird beim Aufheben gebunden\n\"Wo sich für gewöhnlich ein Porträt befindet, ist stattdessen eine Blume zwischen Glas gepresst und präserviert.\"" }
entries[224278] = { ["name"] = "Zeitverzerrte Baupläne aus Eisenschmiede", ["text"] = "Questgegenstand\nEinzigartig" }
entries[224283] = { ["name"] = "Zurückgewonnener Katalysator", ["text"] = "Questgegenstand\n\"Moderat giftig, aber stellt Euch nur die Farben vor!\"" }
entries[224284] = { ["name"] = "Augenlose Blüte", ["text"] = "Questgegenstand\n\"So strahlend, dass es sich fast lohnt, sich durch die Dornen zu kämpfen.\"" }
entries[224285] = { ["name"] = "Leuchtender Würgersaft", ["text"] = "Questgegenstand\n\"Wie soll man sonst das perfekte, perlmuttglänzende Leuchten erreichen?\"" }
entries[224286] = { ["name"] = "Karminkriecher", ["text"] = "Questgegenstand\n\"Am Ende war seine Schönheit sein Untergang.\"" }
entries[224290] = { ["name"] = "Axt des Sturmverteidigers", ["text"] = "Wird bis zum Ausrüsten an Kriegsmeute gebunden\nEinhändig Axt\n798 - 1,658 Schaden Geschwindigkeit 2.60\n(472.3 Schaden pro Sekunde)\n+415 [Beweglichkeit oder Stärke]\n+1.730 Ausdauer\nHaltbarkeit 90 / 90\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, 'Kettenblitzschlag' zwischen 3 Gegnern zu wirken, die jedem von ihnen 23641 Naturschaden zufügen.\nVerkaufspreis:" }
entries[224292] = { ["name"] = "Strahlender Treibstoffsplitter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (45)\nDauer: 15 min (Realzeit)\nBenutzen: Drei strahlende Treibstoffsplitter in strahlende Treibstoffkristalle verwandeln." }
entries[224294] = { ["name"] = "Glitzerstein oder Süßfleisch", ["text"] = "Questgegenstand" }
entries[224296] = { ["name"] = "Korb mit drakonischen Blumen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Mit ihren latenten magischen Energien wurden diese Blumen ursprünglich geerntet, um sie für magisches Feuerwerk zu verwenden. Öffnet ihn, um eine Blume von allen fünf Drachenschwärmen zu erhalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[224297] = { ["name"] = "Traumsprungwiege", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser schimmernde Kokon kann bei Erzdruide Hamuul Runentotem in der Nähe von Traumsprungermittlungen für einen traumgebundenen Ausrüstungsgegenstand Eurer Wahl eingetauscht werden.\"\nVerkaufspreis:" }
entries[224298] = { ["name"] = "Geweiteter Äonenkanister", ["text"] = "Wird beim Aufheben gebunden\n\"Wird in alle Ewigkeit gefüllt, wird doch niemals voll.\"" }
entries[224373] = { ["name"] = "Schillernder Edelstein des Wasserlords", ["text"] = "\"Viele verschiedene Farben wirbeln und schwimmen im Inneren umher. Eure Berührung versetzt was auch immer sich darin befindet in Aufregung, fast schon, als würde es in Wallung geraten, um freizubrechen.\"\nVerkaufspreis:" }
entries[224374] = { ["name"] = "Zügel der donnernden Rubinwolkenschlange", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört eine reitbare donnernde Rubinwolkenschlange oder gibt sie wieder frei. Das ist ein Flugreittier. Benötigt 'Wolkenschlangenreiten' vom Orden der Wolkenschlange.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Von Geburt an fühlen sich donnernde Wolkenschlangen zu Stürmen hingezogen. Sie jagen gerne Blitze durch dunkle, trübe Wolken und lassen Regengüsse auf sich prasseln.\"\nBeute von:\nAlani\nZone:\nTal der Ewigen Blüten" }
entries[224395] = { ["name"] = "Geheimknoblauch", ["text"] = "Questgegenstand\n\"Wie kann so etwas hier gedeihen?\"" }
entries[224396] = { ["name"] = "Zerquetschter Taro", ["text"] = "Questgegenstand\n\"Nun, einen Versuch war es wert.\"" }
entries[224397] = { ["name"] = "Makelloser Taro", ["text"] = "Questgegenstand\n\"Stärkehaltige Perfektion.\"" }
entries[224398] = { ["name"] = "Zügel des Fransenfederhippogryphen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Fransenfederhippogryphen oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser majestätische Hippogryph stammt aus dem Fransenfederhochland von Feralas. Früher hat er seine Jungen beschützt, aber nun dient er einer größeren Sache.\"\nVerkäufer:\nBobadormu\nZone:\nTanaris\nKosten:\n5000\n\nVerkäufer:\nGrannadormu\nZone:\nTanaris\nKosten:\n5000" }
entries[224399] = { ["name"] = "Zügel des Amani-Jagdbären", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen Jagdbären der Amani oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Amanitrolle reiten diese wilde Kreatur auf zeremoniellen Jagden zu Ehren des Bärengottes Nalorakk.\"\nVerkäufer:\nCupri\nZone:\nShattrath\nKosten:\n5.000" }
entries[224400] = { ["name"] = "Sehenbeirennenkerzen", ["text"] = "Questgegenstand\n\"Wer nichts sieht, der auch nicht flieht.\"" }
entries[224401] = { ["name"] = "Weitlauffutter", ["text"] = "Questgegenstand\n\"Vorräte für unterwegs.\"" }
entries[224402] = { ["name"] = "Bastelwerkzeug", ["text"] = "Questgegenstand\n\"Wird sowohl zum Freimachen von Fluchttunneln als auch zum Wiederaufbau von Heimen benutzt.\"" }
entries[224403] = { ["name"] = "Erbstückwachs", ["text"] = "Questgegenstand\n\"Dieses Wachs wird von Generation an Generation weitergegeben und ist die lebendige, klebrige Geschichte des Stamms.\"" }
entries[224404] = { ["name"] = "Verzauberter Speerholzzauberstab", ["text"] = "Wird beim Anlegen gebunden\nDistanz Zauberstab\n270 - 451 Schattenschaden Geschwindigkeit 2.00\n(180.3 Schaden pro Sekunde)\n+1.847 Intelligenz\n+1.162 Ausdauer\n+ 222 Zufallswert 1\n+ 222 Zufallswert 2\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[224405] = { ["name"] = "Szepter der strahlenden Magie", ["text"] = "Wird beim Aufheben gebunden\nDistanz Zauberstab\n907 - 1,513 Feuerschaden Geschwindigkeit 2.00\n(605.0 Schaden pro Sekunde)\n+6.201 Intelligenz\n+4.874 Ausdauer\n+ 364 Zufallswert 1\n+ 364 Zufallswert 2\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[224406] = { ["name"] = "Nebli", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[224407] = { ["name"] = "Bonuserfahrung", ["text"] = "Wird beim Aufheben gebunden\nGewährt zusätzliche Erfahrung für den Sieg über einen Schlachtzugsboss.\n80 ( 80)" }
entries[224408] = { ["name"] = "Bonuserfahrung", ["text"] = "Wird beim Aufheben gebunden\nGewährt zusätzliche Erfahrung für den Sieg über einen Dungeonboss.\n80 ( 80)" }
