entries[224415] = { ["name"] = "Elfenbeinfarbener Goliathus", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese riesigen Käfer verbringen ihr Leben in den finstersten Tunneln Khaz Algars. Obwohl ihnen selbst das kleinste Schimmern künstlichen Sonnenlichts verwehrt wird, schaffen sie es, zu gedeihen.\"\nErfolg:\nRuhm des Tiefenforschers" }
entries[224417] = { ["name"] = "Stapel Flugblätter", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Stapel Flugblätter, der die Wellnessangebote an der Chancenspitze bewirbt.\"" }
entries[224418] = { ["name"] = "Rezept: Alles-im-Eintopf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Alles-im-Eintopf herstellt.\nRezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nBenötigt Ruhmrang 4 beim Konvent der Tiefen.\nVerkaufspreis:" }
entries[224419] = { ["name"] = "Rezept: Herzhafte Narrentafel", ["text"] = "Benutzen: Lehrt Euch, wie man eine herzhafte Narrentafel herstellt.\nRezept für 3 Portionen. Die tatsächliche Anzahl an Portionen hängt von der Kochfertigkeit ab.\nBenötigt Kochkunst von Khaz Algar (35)\nVerkaufspreis:" }
entries[224420] = { ["name"] = "Muster: Gärtnerhut des Kunsthandwerkers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Gärtnerhut des Kunsthandwerkers herstellt.\nBenötigt Schneiderei von Khaz Algar (35)\nVerkaufspreis:" }
