entries[224551] = { ["name"] = "Getränkegutschein", ["text"] = "Questgegenstand\n\"Ein zerfledderter Zettel, auf dem steht: \"Gilt für ein Getränk Eurer Wahl im Kur- und Baderesort Chancenspitze!\"\"" }
entries[224552] = { ["name"] = "Fackel des Höhlenforschers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Zündet eine Fackel an. (5 Sek. Abklingzeit)\n\"Kommt schon! Das Abenteuer wartet!\"\nVerkaufspreis:" }
entries[224553] = { ["name"] = "Beledars Einstimmung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stimmt Euch auf die Störungen von Beledars Schatten ein.\n\nBeledars Brut wird auf der Zonenkarte sichtbar.\nBenötigt Ruhmrang 23 bei den Arathi von Heilsturz.\n\"Ein Fragment, das von Beledars Schatten verderbt wurde.\"" }
entries[224554] = { ["name"] = "Silberstreifszepter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ruft den Wind zu den Waffen. Eure Füße werden den Boden nicht berühren! (5 Min Abklingzeit)\n\"Um ehrlich zu sein, ich liebe die Aussicht von hier oben.\"\nVerkaufspreis:" }
entries[224555] = { ["name"] = "Arbauchs Erinnerungsedelstein", ["text"] = "Questgegenstand\nEinzigartig\n75 ( 75)\n\"Der Erinnerungsedelstein von Vorarbeiter Arbauch. Bringt ihn besser ins Archiv zurück.\"" }
entries[224556] = { ["name"] = "Schließkassette des glorreichen Rivalen", ["text"] = "Wird beim Aufheben gebunden\n\"Ein beeindruckender Vorrat an verschiedenen Waren. Kann Berufsreagenzien, Schriftrollen mit Rezepten, PvP-Verbrauchsgegenstände und mehr enthalten!\"\n<Zum Öffnen rechtsklicken>" }
entries[224557] = { ["name"] = "Gefahrenzuschlag für Feldsanitäter", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Vorrat verschiedener Güter, der für die nicht ausreichend gewürdigte Arbeit auf dem Schlachtfeld entschädigen soll.\"\n<Zum Öffnen rechtsklicken>" }
