entries[224747] = { ["name"] = "Bukanierkeulen", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Streitkolben\n1 - 2 Schaden Geschwindigkeit 2.60\n(0.6 Schaden pro Sekunde)\n+9 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 1 Vielseitigkeit\nHaltbarkeit 90 / 90\nVerkaufspreis:" }
entries[224748] = { ["name"] = "Dreispitz des Kapitäns", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n2 Rüstung\n+3 Intelligenz\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\nErhöht Eure Meisterschaftswertung um + 4.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[224749] = { ["name"] = "Rutschfeste Goblintreter", ["text"] = "Wird beim Aufheben gebunden\nFüße Kette\n4 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\n+ 2 Vielseitigkeit\nHaltbarkeit 65 / 65\nVerkaufspreis:" }
entries[224752] = { ["name"] = "Durchnässter Tagebucheintrag", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erhöht Eure Angelfertigkeit um 10, bis zu einem Maximum von 300.\n80 ( 80)\n\"Kaum entzifferbar, aber vielleicht für jemanden in Eurer Kriegsmeute von Nutzen.\"\nVerkaufspreis:" }
entries[224753] = { ["name"] = "Gurt des Piratenkapitäns", ["text"] = "Wird beim Aufheben gebunden\nTaille Platte\n5 Rüstung\n+2 [Stärke oder Intelligenz]\n+3 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.\n+ 1 Vielseitigkeit\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
entries[224754] = { ["name"] = "Gamaschen des Gildenmeisters", ["text"] = "Wird beim Aufheben gebunden\nBeine Kette\n6 Rüstung\n+3 [Beweglichkeit oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 3 Vielseitigkeit\nHaltbarkeit 100 / 100\nVerkaufspreis:" }
entries[224755] = { ["name"] = "Messerschützer der Defias", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Platte\n4 Rüstung\n+1 [Stärke oder Intelligenz]\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
entries[224756] = { ["name"] = "Krümels Spezialaromen", ["text"] = "Wird beim Aufheben gebunden\nIn Schildhand geführt\n+5 Intelligenz\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\n+ 2 Vielseitigkeit\nVerkaufspreis:" }
entries[224757] = { ["name"] = "Handschuhe des Meisterkochs", ["text"] = "Wird beim Aufheben gebunden\nHände Kette\n3 Rüstung\n+2 [Beweglichkeit oder Intelligenz]\n+3 Ausdauer\nErhöht Eure Tempowertung um + 1.\nErhöht Eure Meisterschaftswertung um + 2.\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
entries[224758] = { ["name"] = "Gestohlener Helm von Sturmwind", ["text"] = "Wird beim Aufheben gebunden\nKopf Platte\n7 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure Tempowertung um + 2.\n+ 3 Vielseitigkeit\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[224759] = { ["name"] = "Armschienen des Piraten", ["text"] = "Wird beim Aufheben gebunden\nHandgelenk Leder\n2 Rüstung\n+1 [Beweglichkeit oder Intelligenz]\n+2 Ausdauer\nErhöht Eure kritische Trefferwertung um + 1.\nErhöht Eure Tempowertung um + 1.\nHaltbarkeit 50 / 50\nVerkaufspreis:" }
entries[224760] = { ["name"] = "Kuller", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben." }
entries[224761] = { ["name"] = "Schnelldochtkerzenset", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt ein Wachsabbild von Euch an Eurer aktuellen Position auf. (40 Sek. Abklingzeit)\n\"Mit diesem Kerzenset können mehrere kleine Kerzen gezogen werden. Oder eine große Wachsfigur.\"" }
entries[224762] = { ["name"] = "Trinkschlauch des Tiefenforschers", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 375000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nVerkaufspreis:" }
entries[224763] = { ["name"] = "Vorlage: Kubischer Blasphemit", ["text"] = "Benutzen: Lehrt Euch, wie man einen kubischen Blasphemit herstellt.\nZum Schleifen von hochwertigem kubischen Blasphemit wird eine Spezialisierung in den Juwelenschleiftechniken der vier begehrtesten Edelsteine von Khaz Algar benötigt. Selbst eine billige Kopie bedarf einer meisterhaften Technik.\nBenötigt Juwelierskunst von Khaz Algar\n(50)\nVerkaufspreis:" }
entries[224764] = { ["name"] = "Mooswollenfaden", ["text"] = "Handwerksmaterial\n\"Aus der Wolle der Schafe auf der Insel von Dorn gesponnen. Der Faden ist ebenso fest wie vielseitig und bei Verkäufern von Schneiderbedarf erhältlich.\"\nVerkaufspreis:" }
entries[224765] = { ["name"] = "Ewig brennende Zündung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Entzündet die Schmiede.\n\nErlangt für 10 Min. Genialität, Mehrfachherstellung und Einfallsreichtum basierend auf Eurer Immerflammenschmiede-Spezialisierung.\n\"Von Eurem Können mit der Schmiede gewonnen.\"\nVerkaufspreis:" }
entries[224766] = { ["name"] = "Treuer Hund", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[224767] = { ["name"] = "Riesige Kerzenteile", ["text"] = "\"Das Wachs soll für Dagran nützlich sein. Vielleicht schreibt er eine gute Doktorarbeit über die Effekte von Wachs auf die Taschen von Abenteurern.\"" }
entries[224768] = { ["name"] = "Bauplan für das Luftschiff des Tiefenforschers: Flügelpropeller", ["text"] = "Luftschiffbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für das Luftschiff des Tiefenforschers frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[224769] = { ["name"] = "Bauplan für das Luftschiff des Tiefenforschers: Rotorblätter", ["text"] = "Luftschiffbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für das Luftschiff des Tiefenforschers frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[224770] = { ["name"] = "Bauplan für das Luftschiff des Tiefenforschers: Frontpropeller", ["text"] = "Luftschiffbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für das Luftschiff des Tiefenforschers frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[224771] = { ["name"] = "Bauplan für das Luftschiff des Tiefenforschers: Leitwerk", ["text"] = "Luftschiffbauplan\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für das Luftschiff des Tiefenforschers frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[224772] = { ["name"] = "Kopfgeld von Gallywix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"In diesen Befehlen wird ein großes Kopfgeld für den Düsternisverschmolzenen ausgelobt, der herausfindet, wer für die Öffnung des Walls an der Chancenspitze verantwortlich ist.\"" }
entries[224773] = { ["name"] = "Schnickschnacks rote Kerze", ["text"] = "Questgegenstand\n\"Eine Kerze aus tiefrotem Wachs. Ihr wollt nicht wissen, wie die Kobolde an diese Farbe kamen.\"" }
entries[224774] = { ["name"] = "Schnickschnacks Trankflasche", ["text"] = "Questgegenstand\n\"Eine zähe, undefinierbare Flüssigkeit benetzt die Innenseite dieser Glasflasche.\"" }
entries[224775] = { ["name"] = "Schnickschnacks ganz echte Rubine", ["text"] = "Questgegenstand\n\"Ein paar ungeschliffene rote Edelsteine. Sie sind von moderater Qualität und es ist unklar, ob es überhaupt echte Rubine sind.\"" }
entries[224777] = { ["name"] = "Schattenwerfer der Sureki", ["text"] = "Questgegenstand\nEinzigartig\n\"Die Neruber nutzen diese Emitter, um Befehle und Nachrichten ranghoher Anführer zu übertragen.\"" }
entries[224778] = { ["name"] = "Schnickschnacks Größermacher", ["text"] = "Questgegenstand\n\"Der Größermacher sieht aus wie ein Werkzeug der Irdenen zur Juwelenbearbeitung, das der Vergrößerung dient.\"" }
entries[224779] = { ["name"] = "Alhainrs Schädel", ["text"] = "Questgegenstand\n\"Kleine Blätter und Ranken sprießen aus dem Schädel.\"" }
entries[224780] = { ["name"] = "Gehärteter Gewitterpelz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen von Khaz Algar um 1 zu erhöhen.\n\"Ein besonders struppiger Pelz, der nicht formbar genug für Handarbeiten ist. Ihr könnt ihn aber studieren, um die eine oder andere Sache über die örtliche Tierwelt zu lernen.\"" }
entries[224781] = { ["name"] = "Abyssischer Pelz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen von Khaz Algar um 2 zu erhöhen.\n\"Ein kleines Fellbüschel mit tief lila Färbung. Man kann damit nicht viel anfangen, aber ein so faszinierendes und seltenes Objekt findet man nicht oft.\"" }
entries[224782] = { ["name"] = "Messerscharfe Klaue", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen von Khaz Algar um 1 zu erhöhen.\n\"Die kleine, aber extrem scharfe Klaue einer Kreatur. Sie ist zwar nicht groß genug, um für irgendetwas gut zu sein, ist aber ein faszinierendes Forschungsobjekt.\"" }
entries[224783] = { ["name"] = "Truhe des adeligen Aufputzes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Stellt eine Truhe mit königlicher Kleidung auf, die Ihr und andere anprobieren könnt. (1 Stunde Abklingzeit)\n\"Nur denen mit erlesenstem Geschmack vorbehalten.\"\nVerkaufspreis:" }
entries[224784] = { ["name"] = "Kiste des Gipfels", ["text"] = "Wird beim Aufheben gebunden\n\"Wöchentliche Truhe mit Materialien zur Aufwertung von Ausrüstung, Gold, Ausrüstungsgegenständen des Abenteurers und vielem mehr.Die ersten vier wöchentlichen Truhen, die Ihr Euch jede Woche verdient, enthalten Kastenschlüsselsplitter.\"\n<Zum Öffnen rechtsklicken>" }
entries[224786] = { ["name"] = "Kleidung des Skelettkönigs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwandelt sich in den Skelettkönig. (3 Sek. Abklingzeit)" }
entries[224791] = { ["name"] = "Tracht des goldenen Lordregenten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwandelt sich in einen goldenen Lordregenten. (3 Sek. Abklingzeit)" }
entries[224792] = { ["name"] = "Blutrote Aristokratenkleidung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verwandelt sich in einen heiteren Aristokraten. (3 Sek. Abklingzeit)" }
entries[224797] = { ["name"] = "Zirdos Geschäftsbuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Das Geschäftsbuch offenbart Schwarzblutlieferungen in Lorenhall, die von Noggenfogger, dem Handelsprinzen des Dampfdruckkartells, abgesegnet wurden.\"" }
entries[224799] = { ["name"] = "Nizreks Trank", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Stellt die Vitalität eines Verbündeten wieder her. (2 Sek. Abklingzeit)\n\"Eine Phiole mit einer schwach leuchtenden Flüssigkeit.\"" }
entries[224807] = { ["name"] = "Notizen des Algarikürschners", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kürschnereiwissen von Khaz Algar um 3 zu erhöhen." }
entries[224808] = { ["name"] = "Opalerz", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Wichtige Teile eines verlorenen Puzzles.\"" }
entries[224809] = { ["name"] = "Rohr des irdenen Klempners", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lenkt das Wasser durch das uralte Rohrsystem, um die Verstopfung zu beseitigen. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[224810] = { ["name"] = "Holzwurmelixier", ["text"] = "Questgegenstand\nEinzigartig\n\"Aus holzbohrenden Würmern gewonnen. In der Stadt der Fäden berühmt, obwohl es nahezu ungenießbar ist.\"" }
entries[224811] = { ["name"] = "Zuckerpilze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Die Fungusessenz wandelt Eure Gestalt und erhöht 30 Sek. lang das Tempo um 25%.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten. (30 Sek. Abklingzeit)\nBenötigt Ruhmrang 12 bei den Arathi von Heilsturz.\n\"Kinder lieben es, nach diesen süßen Leckerbissen zu suchen!\"\nVerkaufspreis:" }
entries[224813] = { ["name"] = "Großkatzenpfeife", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Beschwört einen großen Kampfluchs, der Euch 5 Min. lang im Kampf zur Seite steht.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten. (5 Min Abklingzeit)\nBenötigt Ruhmrang 12 bei den Arathi von Heilsturz.\n\"Der größte Luchs ist immer nur ein Pfeifen entfernt.\"\nVerkaufspreis:" }
entries[224814] = { ["name"] = "Kriegsmeutengebundene Stiefel des Abenteurers", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 1 freigeschaltet.\n\"Enthält einen 4/8-Ausrüstungsgegenstand des Abenteurers entsprechend Eurer Klasse.\"\nVerkaufspreis:" }
entries[224815] = { ["name"] = "Glücksbringer der Flamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (20)\nBenutzen: Erfüllt Euch mit der Heiligen Flamme, sodass Eure Angriffe und Fähigkeiten gelegentlich einen Elementar des Lichts erschaffen, der Zielen 3 Heiligschaden zufügt.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten.\nBenötigt Ruhmrang 12 bei den Arathi von Heilsturz.\n\"Der schwindende Bestand wird von den Arathor rapide ausgedünnt.\"\nVerkaufspreis:" }
entries[224816] = { ["name"] = "Neruberischer Almanach", ["text"] = "\"Die Seiten sind mit kaum entzifferbaren Diagrammen und Graphen übersät. Das Einzige, was einigermaßen erkennbar ist, ist eine Zeichnung von seismischen Wellen, die ein Tunnelsystem darunter darstellen.\"\nVerkaufspreis:" }
entries[224817] = { ["name"] = "Notizen des Algarikräuterkundigen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen von Khaz Algar um 3 zu erhöhen." }
entries[224818] = { ["name"] = "Notizen des Algariminenarbeiters", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Bergbauwissen von Khaz Algar um 3 zu erhöhen." }
entries[224822] = { ["name"] = "Schrott durchforsten", ["text"] = "\"Durchforstet Schrott um Teile, vergessene Prototypen und mehr zu finden!\"" }
entries[224831] = { ["name"] = "Würfel der unendlichen Erfindungen (Nur PTR)", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Setzt die Abklingzeit der Ingenieurskunst von Khaz Algar zurück.\n\nDieser Gegenstand dient ausschließlich Testzwecken.\nBenötigt Ingenieurskunst von Khaz Algar (1)\n\"Zählt als Samophlang, was auch immer das ist.\"" }
entries[224835] = { ["name"] = "Tiefenhainwurzeln", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Kräuterkundewissen von Khaz Algar um 1 zu erhöhen.\n\"Die Wurzeln wachsen weiter, auch nachdem die Rose gepflückt wurde. Nicht wirklich für irgendwas zu gebrauchen, aber ein interessantes Studienobjekt.\"" }
entries[224837] = { ["name"] = "Verfluchte Hacke", ["text"] = "Wird bis zum Ausrüsten an Kriegsmeute gebunden\nEinhändig Axt\n1,180 - 2,452 Schaden Geschwindigkeit 2.60\n(698.5 Schaden pro Sekunde)\n+614 [Beweglichkeit oder Stärke]\n+3.002 Ausdauer\nErhöht Eure kritische Trefferwertung um + 424.\nErhöht Eure Tempowertung um + 170.\nHaltbarkeit 90 / 90\nWenn dieser Gegenstand in Euren Taschen ist, ausgerüstet ist oder für eine Transmogrifikation verwendet wird, werdet Ihr gelegentlich vom Fluch verzehrt.\n\"Uralte Runen verzieren den metallischen Kopf und Schwanz und folgen dem Griff in tiefen Gravuren. Die Muster werden zum Knauf hin unregelmäßiger, bis sie nur noch wildes Gekritzel sind.\"\nVerkaufspreis:" }
entries[224838] = { ["name"] = "Nullsplitter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Bergbauwissen von Khaz Algar um 1 zu erhöhen.\n\"Ein winziger Splitter Nullstein, der eine pulsierende Aura der Leere verströmt. Er ist nicht sonderlich nützlich für Handwerksarbeiten, aber Ihr könntet mehr über Algari-Erze und -Mineralien lernen, indem Ihr ihn studiert.\"" }
entries[224839] = { ["name"] = "Kriegsmeutengebundene Gelenkbänder des Abenteurers", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 1 freigeschaltet.\n\"Enthält einen 4/8-Ausrüstungsgegenstand des Abenteurers entsprechend Eurer Klasse.\"\nVerkaufspreis:" }
