entries[224841] = { ["name"] = "Kriegsmeutengebundene Schultern des Abenteurers", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 1 freigeschaltet.\n\"Enthält einen 4/8-Ausrüstungsgegenstand des Abenteurers entsprechend Eurer Klasse.\"\nVerkaufspreis:" }
entries[224842] = { ["name"] = "Kriegsmeutengebundene Beinlinge des Abenteurers", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 1 freigeschaltet.\n\"Enthält einen 4/8-Ausrüstungsgegenstand des Abenteurers entsprechend Eurer Klasse.\"\nVerkaufspreis:" }
entries[224843] = { ["name"] = "Kriegsmeutengebundenes Kopfstück des Abenteurers", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 1 freigeschaltet.\n\"Enthält einen 4/8-Ausrüstungsgegenstand des Abenteurers entsprechend Eurer Klasse.\"\nVerkaufspreis:" }
entries[224844] = { ["name"] = "Kriegsmeutengebundene Handschuhe des Abenteurers", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 1 freigeschaltet.\n\"Enthält einen 4/8-Ausrüstungsgegenstand des Abenteurers entsprechend Eurer Klasse.\"\nVerkaufspreis:" }
entries[224845] = { ["name"] = "Kriegsmeutengebundener Brustharnisch des Abenteurers", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nWird durch Fortschreiten in \"Reise des Tiefenforschers\" in Saison 1 freigeschaltet.\n\"Enthält einen 4/8-Ausrüstungsgegenstand des Abenteurers entsprechend Eurer Klasse.\"\nVerkaufspreis:" }
entries[224846] = { ["name"] = "Frostknallkanister", ["text"] = "Questgegenstand\n\"Die großen Kühlcontainer der Venture Company sind eiskalt.\"" }
entries[224852] = { ["name"] = "Das abgetrennte Säckchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n36 Platz Tasche\nAnlegen: Erhöht den maximalen Ertrag beim Zerfasern von Khaz Algar um 1.\n\n[ Anlegeeffekt erfordert Schneiderei von Khaz Algar 1 ][ Anlegeeffekt erfordert Schneiderei von Khaz Algar 1 ]\n\"Ein Behälter, der von den Meisterhandwerkern der Weberin gesponnen wurde, die den Wert von so seltenem Stoff wie Morgengespinst und Dämmergespinst voll ausnutzen.\"" }
entries[224853] = { ["name"] = "Abenteurerrundbandhelm", ["text"] = "Wird beim Aufheben gebunden\nKopf Leder\n20 Rüstung\n+18 [Beweglichkeit oder Intelligenz]\n+26 Ausdauer\nErhöht Eure kritische Trefferwertung um + 22.\nErhöht Eure Meisterschaftswertung um + 12.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[224854] = { ["name"] = "Heiliges Tuch", ["text"] = "Wird beim Aufheben gebunden\nKopf Stoff\n11 Rüstung\n+18 Intelligenz\n+26 Ausdauer\nErhöht Eure Tempowertung um + 12.\n+ 22 Vielseitigkeit\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
entries[224855] = { ["name"] = "Helm von Narv", ["text"] = "Wird beim Aufheben gebunden\nKopf Kette\n29 Rüstung\n+18 [Beweglichkeit oder Intelligenz]\n+26 Ausdauer\nErhöht Eure kritische Trefferwertung um + 22.\nErhöht Eure Tempowertung um + 12.\nHaltbarkeit 85 / 85\nVerkaufspreis:" }
