entries[225241] = { ["name"] = "Runderneuerte Tüftelei: Alarmgeschütz 2000", ["text"] = "Tüfteleimodul\nEinzigartig anlegbar: Alarmgeschütz 2000 (1)\nRunderneuertes Alarmgeschütz 2000\nAnlegen: Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nAlarmgeschütz 2000\nPlatziert ein verborgenes Alarmgeschütz 2000 an einer Zielposition in der Nähe. Falls ein gegnerischer Spielercharakter dessen Entdeckungsradius betritt, macht es Euch auf diesen aufmerksam und versucht 30 Sek. lang, oder bis es zerstört wird, den Bereich zu verteidigen.\n\"Runderneuert für den Gebrauch in Khaz Algar-Ausrüstung. Erfolgschance entspricht der einer Algari-Tüftelei mittlerer Qualität.\"\nVerkaufspreis:" }
entries[225242] = { ["name"] = "Runderneuerte Tüftelei: Ebenenvertauscher", ["text"] = "Tüfteleimodul\nEinzigartig anlegbar: Ebenenvertauscher (1)\nRunderneuerter Ebenenvertauscher\nAnlegen: Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nEbenenvertauscher\nGewährt dem Benutzer 14-18 Sek. lang Unsichtbarkeit.\n\"Runderneuert für den Gebrauch in Khaz Algar-Ausrüstung. Erfolgschance entspricht der einer Algari-Tüftelei mittlerer Qualität.\"\nVerkaufspreis:" }
entries[225243] = { ["name"] = "Runderneuerte Tüftelei: Teilchenbeschleuniger 2000", ["text"] = "Tüfteleimodul\nEinzigartig anlegbar: Teilchenbeschleuniger 2000 (1)\nRunderneuerter Teilchenbeschleuniger 2000\nAnlegen: Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nTeilchenbeschleuniger 2000\nFixiert einen bis zu 12 bis 60 Meter entfernten Gegner als Ziel. Wenn Euer Weg nach 1.5 Sek. frei von Hindernissen bleibt, stürmt Ihr mit Schallgeschwindigkeit vorwärts. Wenn es zur Kollision kommt, werdet Ihr und das Ziel für 1.5 Sek. betäubt.\nBenötigt Ingenieurskunst der Dracheninseln (1)\n\"Runderneuert für den Gebrauch in Khaz Algar-Ausrüstung. Erfolgschance entspricht der einer Algari-Tüftelei mittlerer Qualität.\"\nVerkaufspreis:" }
entries[225244] = { ["name"] = "Runderneuerte Tüftelei: Schattenflammenraketen", ["text"] = "Tüfteleimodul\nEinzigartig anlegbar: Schattenflammenraketen (1)\nRunderneuerte Schattenflammenraketen\nAnlegen: Für den folgenden Effekt in einen Tüfteleisockel einsetzen:\n\nSchattenflammenraketen\nSpringt auf ein Holzbrett, an das willkürlich Schattenflammenraketen genagelt wurde. Da kann gar nichts schiefgehen, aber wenn doch, würde das 31949 Schattenflammenschaden verursachen, die zwischen Euch und allen Gegnern aufgeteilt würden, die von der theoretischen Explosion getroffen werden.\n\"Runderneuert für den Gebrauch in Khaz Algar-Ausrüstung. Erfolgschance entspricht der einer Algari-Tüftelei mittlerer Qualität.\"\nVerkaufspreis:" }
entries[225245] = { ["name"] = "Überquellender Schatz der Tiefen", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete des Konvents der Tiefen erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[225246] = { ["name"] = "Überquellender Schatz von Heilsturz", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete der Arathi von Heilsturz erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[225247] = { ["name"] = "Überquellender Schatz der Durchtrennten Fäden", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete der Durchtrennten Fäden erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
entries[225249] = { ["name"] = "Klimpernde Tasche mit Gold", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnen, um etwas Gold zu erhalten." }
entries[225250] = { ["name"] = "Sternenberührtes Fellknäuel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein Sternenberührtes Fellknäuel oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein früher ewiger Reisender stieß auf das Fellknäuel und freundete sich mit ein paar von seiner Art an. Diese Fellknäuelkätzchen begleiteten den Reisenden zurück in sein Reich und wurden dadurch und den Aufenthalt dort für immer verändert.\"\nWoW-Shop" }
entries[225251] = { ["name"] = "Erfindung zerlegen", ["text"] = "\"Zerlegt eine unerwünschte Erfindung, um etwas Schrott zu erhalten und ihr Innenleben zu untersuchen.\"" }
entries[225252] = { ["name"] = "Bronzedrachenfeierabzeichen", ["text"] = "Wird an Kriegsmeute gebunden" }
entries[225253] = { ["name"] = "Flackernder Flammenhalter", ["text"] = "Benutzen: Eine einfache Kerze, die trübes Licht spendet.\n\nMit diesem Licht findet Ihr versteckte Gegenstände in Blüte des Lichts und nahen Schlüsselflammengebieten. (15 Sek. Abklingzeit)\n\"Dieser Gegenstand findet sich in den meisten Häusern von Heilsturz.\"\nVerkaufspreis:" }
entries[225256] = { ["name"] = "PH_2", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n78 ( 78)" }
entries[225335] = { ["name"] = "Schmugglerschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Trotz einiger Blutspritzer scheint dieser Schlüssel in gutem Zustand zu sein. Sieht aus, als wäre er möglicherweise für einen großen Fels gedacht.\"\nVerkaufspreis:" }
entries[225336] = { ["name"] = "Ein verlorener Schuh", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Der Name Gerta ist in den Futterstoff gestickt.\"" }
entries[225337] = { ["name"] = "Violetter Sporenbiss", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[225338] = { ["name"] = "Glyphe 'Hieb'", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Mönch\nBenutzen: 'Tigerklaue' trifft Euer Ziel jetzt mit der ausgerüsteten Waffe.\nVerkaufspreis:" }
entries[225339] = { ["name"] = "Hühnereier", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein seltsamer Ort für Eier. Wo ist das Huhn?\"" }
entries[225340] = { ["name"] = "Kaiserlicher Schaumwein", ["text"] = "Questgegenstand\n\"Aus Trauben gewonnen, die in Beledars Licht gebadet wurden. Hat ordentliche Umdrehungen.\"" }
entries[225341] = { ["name"] = "Belastender Dolch", ["text"] = "Questgegenstand\n\"Strahlt eine beunruhigende Aura aus.\"" }
