entries[225343] = { ["name"] = "Belastender Tagebucheintrag", ["text"] = "Questgegenstand\n\"Ein flimmernder Stein, der in einen Schattenwerfer der Neruber passt, um eine aufgezeichnete Nachricht abzuspielen.\"" }
