entries[225548] = { ["name"] = "Wicks Leine", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er wurde vor dem unbarmherzigen Angriff des alten Wachsbart und der drohenden Gefahr der Dunkelheit gerettet und kann nun in Ruhe an losem Wachs knabbern.\"\nBeute:\nDie Dunkelheit\nZone:\nDunkelflammenspalt (Mythisch)\n\nBeute:\nSchatz des Herausforderers\nZone:\nDunkelflammenspalt" }
