entries[225553] = { ["name"] = "PH_5", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n78 ( 78)" }
entries[225554] = { ["name"] = "Sonnenloser Köder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Matscht einen sonnenlosen Köder, einen Trübflossenköder, eine hungernde Schimmerflosse und einen Nekrostab der Zornflossen zusammen. Wird schon passen.\n\"Vom Kopf einer Illusion gezogen, die Kobyss am Sonnenlosen Strand erscheinen ließ. Mit genug Exemplaren könntet Ihr es ihnen vielleicht mit gleicher Münze heimzahlen.\"\nVerkaufspreis:" }
entries[225555] = { ["name"] = "Amulett der reinen Flamme", ["text"] = "Questgegenstand\nBenutzen: Tragt ein Parfüm auf, das Eure Zauber und Waffen mit heiligem Feuer verstärkt. (3s Abklingzeit) (30 Sek. Abklingzeit)\n\"Nach Beledars Abbild gefertigt.\"" }
entries[225556] = { ["name"] = "Uraltes Konstrukt", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört am Zielort Ikarus, den Unzerbrechlichen, der 1 Min. lang bestehen bleibt. Dieser dient als Zielattrappe und kann von der jeweils entgegengesetzten Rolle geheilt werden oder Schaden durch sie erleiden, solange sie bestehen bleibt. Wie weit könnt Ihr die Zahlen steigen lassen?\n\nKann nur im Freien eingesetzt werden. (1 Stunde Abklingzeit)" }
entries[225557] = { ["name"] = "Zischender Glutpollen", ["text"] = "Wird an Kriegsmeute gebunden\n\"Verursacht äußerst schmerzhafte Niesanfälle. Vielleicht hat die Metbrauerei Verwendung dafür.\"\nVerkaufspreis:" }
entries[225558] = { ["name"] = "Trübflossenköder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Matscht einen sonnenlosen Köder, einen Trübflossenköder, eine hungernde Schimmerflosse und einen Nekrostab der Zornflossen zusammen. Wird schon passen.\n\"Bei einem Kobyss gefunden, der Euch in Velhans Geltung zum Narren halten wollte. Mit genügend Teilen könntet Ihr damit das Blatt wenden.\"\nVerkaufspreis:" }
entries[225559] = { ["name"] = "Hungernde Schimmerflosse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Matscht einen sonnenlosen Köder, einen Trübflossenköder, eine hungernde Schimmerflosse und einen Nekrostab der Zornflossen zusammen. Wird schon passen.\n\"Ihr habt diese schimmernde Schuppe einem Kobyss entnommen, der Euch mit einer Illusion im Lauernden Strudel verwirren wollte.\"\nVerkaufspreis:" }
entries[225560] = { ["name"] = "Nekrostab der Zornflossen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Matscht einen sonnenlosen Köder, einen Trübflossenköder, eine hungernde Schimmerflosse und einen Nekrostab der Zornflossen zusammen. Wird schon passen.\n\"Den Nekromagiern der Zornflossen entwendet. Er pulsiert vor Macht. Vielleicht könnte er eine Wendung gegen die Kobyss herbeiführen.\"\nVerkaufspreis:" }
