entries[225573] = { ["name"] = "Das Kapital des Wesirs", ["text"] = "Wird beim Aufheben gebunden\n\"Wöchentliche Truhe mit Materialien zur Aufwertung von Ausrüstung, Gold, Ausrüstungsgegenständen des Abenteurers und vielem mehr.Die ersten vier wöchentlichen Truhen, die Ihr Euch jede Woche verdient, enthalten Kastenschlüsselsplitter.\"\n<Zum Öffnen rechtsklicken>" }
entries[225574] = { ["name"] = "Schwingen der zerschmetterten Trauer", ["text"] = "Wird beim Aufheben gebunden\nRücken\n1222 Rüstung\n+1.133 [Beweglichkeit oder Stärke oder Intelligenz]\n+5.034 Ausdauer\nErhöht Eure kritische Trefferwertung um + 563.\nErhöht Eure Tempowertung um + 225.\nAnlegen: Wenn Ihr Schaden in Höhe von mehr als 25% Eurer Gesundheit erleidet, erhaltet Ihr 10 Sek. lang 1802 Vermeidung und 10% mehr Heilung. Dieser Effekt kann nur einmal alle 90 Sek. auftreten.\n\nVerringert Fallschaden. (1.5Min. Abklingzeit)\nVerkaufspreis:" }
entries[225575] = { ["name"] = "Gunst des seidenen Beraters", ["text"] = "Wird beim Aufheben gebunden\nHals\n+5.034 Ausdauer\n+ 2.689 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 556.\n\"Für die Treue, Weisheit und vor allem Einigkeit meiner treuesten Berater.\"\nVerkaufspreis:" }
entries[225576] = { ["name"] = "Zuckender Ringwurm", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+5.034 Ausdauer\nErhöht Eure Tempowertung um + 742.\nErhöht Eure Meisterschaftswertung um + 2.504.\n\"Ist es am Leben? Vielleicht. Ist es modisch? ... Vielleicht.\"\nVerkaufspreis:" }
entries[225577] = { ["name"] = "Insigne des Zeloten der Sureki", ["text"] = "Wird beim Aufheben gebunden\nHals\n+5.034 Ausdauer\nErhöht Eure Tempowertung um + 2.735.\nErhöht Eure Meisterschaftswertung um + 510.\nAnlegen: Wenn ein Verbündeter Euch direkt heilt, besteht eine hohe Chance, dass Euer Verbündeter 3125 Mana wiederherstellt und Ihr beide 10 Sek. lang 279 Vielseitigkeit erhaltet.\nVerkaufspreis:" }
entries[225578] = { ["name"] = "Siegel des vergifteten Pakts", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nFinger\n+5.034 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.782.\nErhöht Eure Meisterschaftswertung um + 464.\nAnlegen: Das Verursachen von Schaden hat eine hohe Chance, Euch eine Dosis ' Giftiges Potenzial ' zu gewähren. Bei 5 Dosen injiziert Ihr sie in Euer Ziel und verursacht damit im Verlauf von 3 Sek. ( 1 * 262010 ) Naturschaden.\n\nDas Verursachen von Naturschaden hat eine Chance, Euch eine zusätzliche Dosis zu gewähren.\nVerkaufspreis:" }
